<?php $page_title='Order Details';require 'includes/header.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT * FROM orders WHERE id=?");$s->execute([$id]);$o=$s->fetch();if(!$o){exit('Order not found.');}$s=$pdo->prepare("SELECT * FROM order_items WHERE order_id=?");$s->execute([$id]);$items=$s->fetchAll();?>
<div class="page-head"><div><h1>Order #<?=$o['id']?></h1><p><?=date('F d, Y · H:i',strtotime($o['created_at']))?></p></div><a class="btn light" href="orders.php">← Orders</a></div><div class="order-grid"><div class="panel"><h2>Customer details</h2><div class="kv"><b>Name</b><span><?=e($o['customer_name'])?></span></div><div class="kv"><b>Email</b><span><?=e($o['customer_email'])?></span></div><div class="kv"><b>Phone</b><span><?=e($o['phone'])?></span></div></div><div class="panel"><h2>Shipping details</h2><div class="kv"><b>Address</b><span><?=e($o['shipping_address'])?></span></div><div class="kv"><b>City</b><span><?=e($o['city'])?></span></div><div class="kv"><b>Country</b><span><?=e($o['country'])?></span></div><div class="kv"><b>Postal</b><span><?=e($o['postal_code'])?></span></div></div></div><div class="panel" style="margin-top:18px"><h2>Order & payment</h2><div class="mini-grid"><div class="mini"><small>Payment</small><b><?=e(strtoupper($o['payment_method']))?></b></div><div class="mini"><small>Payment status</small><b><?=e(ucfirst($o['payment_status']))?></b></div><div class="mini"><small>Order status</small><b><?=e(ucfirst($o['order_status']))?></b></div></div></div><div class="panel" style="margin-top:18px"><h2>Ordered products</h2><div class="table-wrap"><table><tr><th>Product</th><th>Product ID</th><th>Category</th><th>Price</th><th>Qty</th><th>Discount</th><th>Subtotal</th></tr><?php foreach($items as $i):?><tr><td><strong><?=e($i['product_name'])?></strong></td><td><?=e((string)$i['product_id'])?></td><td><?=e($i['category_name']??'—')?></td><td><?=money((float)$i['unit_price'])?></td><td><?=$i['quantity']?></td><td><?=money((float)$i['discount'])?></td><td><?=money((float)$i['subtotal'])?></td></tr><?php endforeach;?></table></div></div><div class="panel" style="margin-top:18px;max-width:450px;margin-left:auto"><h2>Order summary</h2><?php foreach(['subtotal'=>'Subtotal','discount'=>'Discount','shipping'=>'Shipping','tax'=>'Tax','total'=>'Final Total'